@pytest.mark.parametrize("symbol", ("RATS", "GOBLINS", "BANDITS"))
def test_resolved_starter_catalog_preserves_all_fields(symbol):
    resolved = getattr(prepared, symbol)
    actual = normalize(resolved)
    for member in actual[2]:
        assert member["base_id"] == member["variant_id"]
        member["base_id"] = None
    assert numeric_snapshot(actual) == numeric_snapshot(current_expected(resolved[0].id))


@pytest.mark.parametrize(
    "package,symbol",
    (("rat_catalog", "RAT_FAMILY"), ("goblin_catalog", "GOBLIN_FAMILY"), ("bandit_catalog", "BANDIT_FAMILY")),
)
def test_authored_family_resolves_exact_snapshot(package, symbol):
    from importlib import import_module

    from src.backend.features.monsters.catalog.nested_contracts import resolve_family

    data = getattr(import_module(f"src.backend.features.monsters.catalog.families.{package}.family"), symbol)
    family, clans, members = resolve_family(data)
    actual = normalize((family, clans[0], members))
    for member in actual[2]:
        assert member["base_id"] == member["variant_id"]
        member["base_id"] = None
    assert numeric_snapshot(actual) == numeric_snapshot(current_expected(data.id))


def test_active_starter_catalogs_do_not_import_historical_authoring_sources():
    import subprocess
    import sys

    source = """
import sys
from src.backend.features.monsters.catalog.registry import get_catalog
get_catalog()
forbidden = (
    'src.backend.features.monsters.catalog.families.bandits',
    'src.backend.features.monsters.catalog.families.goblins',
    'src.backend.features.monsters.catalog.families.prepared_rats',
    'src.backend.features.monsters.catalog.presentation',
)
assert not set(forbidden).intersection(sys.modules)
"""
    result = subprocess.run([sys.executable, "-c", source], capture_output=True, text=True, timeout=30)
    assert result.returncode == 0, result.stderr


def test_anchor_relic_stays_on_unchanged_historical_definition():
    from src.backend.features.monsters.catalog.authoring import define_base_clan
    from src.backend.features.monsters.catalog.families.system.anchor_sovereigns import ANCHOR_SOVEREIGNS_FAMILY

    expected = define_base_clan(
        ANCHOR_SOVEREIGNS_FAMILY,
        family_name="Владыки якорей",
        clan_id="anchor_sovereigns.base",
        clan_name="Владыки якорей",
        normal_spawn=False,
        presentation={},
        assembly_costs={member.variant_id: member.assembly_cost for member in prepared.ANCHORS[2]},
    )
    assert normalize(prepared.ANCHORS) == normalize(expected)


def numeric_snapshot(value):
    if isinstance(value, dict):
        return {key: numeric_snapshot(item) for key, item in value.items() if key not in {"name", "description", "narrative_hint", "text_id", "image_source", "equipment_set_id", "equipment_source", "assembly_cost"}}
    if isinstance(value, list):
        return [numeric_snapshot(item) for item in value]
    return value


def current_expected(family_id):
    """Keep migration snapshot frozen; apply only approved T0 minion balance changes."""
    from copy import deepcopy

    expected = deepcopy(BEFORE[family_id])
    if family_id == "bandit_gang":
        for member in expected[2]:
            member["min_tier"] = member["mechanics"]["min_tier"] = 1
    from tests.backend.features.monsters.catalog.alpha_expectations import approved_mechanics

    for member in expected[2]:
        member["mechanics"] = approved_mechanics(family_id, member["variant_id"], member["mechanics"])
    return expected
